use lwe_rust::kyber::kem::{keygen_internal, encaps_internal, decaps_internal, Ciphertext, DecapsulationKey, EncapsulationKey, MlKem512};
use lwe_rust::kyber::pke::{ML_KEM_512, ML_KEM_768, ML_KEM_1024};
use rand::RngCore;

#[test]
fn test_kat_ml_kem_512_keygen() {
    let d_hex = "3DEF73C558E1F5F2BFB4F6EAA36EE200CDF54580958CC2176282628FF508A016";
    let z_hex = "B9958575128F97022525266064F9422E83F75FBDCD0F2BC2648655F0E31A17E5";
    let ek_expected_hex = "";
    let dk_expected_hex = "";

    let d = hex::decode(d_hex).unwrap();
    let z = hex::decode(z_hex).unwrap();
    let ek_expected = hex::decode(ek_expected_hex).unwrap();
    let dk_expected = hex::decode(dk_expected_hex).unwrap();

    let mut d_array = [0u8; 32];
    d_array.copy_from_slice(&d);
    let mut z_array = [0u8; 32];
    z_array.copy_from_slice(&z);

    let (ek, dk) = keygen_internal::<800, 1632>(&ML_KEM_512, &d_array, &z_array);
    println!(
        "Expected ek rho: {:?}",
        &ek_expected[ek_expected.len() - 32..]
    );
    println!("Actual ek rho:   {:?}", &ek.0[ek.0.len() - 32..]);

    assert_eq!(ek.0.as_slice(), ek_expected.as_slice(), "Public key mismatch");
    assert_eq!(dk.0.as_slice(), dk_expected.as_slice(), "Secret key mismatch");
}

#[test]
fn test_ml_kem_512_roundtrip() {
    let mut rng = rand::thread_rng();
    let mut d = [0u8; 32];
    let mut z = [0u8; 32];
    rng.fill_bytes(&mut d);
    rng.fill_bytes(&mut z);
    
    let (ek, dk) = keygen_internal::<800, 1632>(&ML_KEM_512, &d, &z);
    
    let mut m = [0u8; 32];
    rng.fill_bytes(&mut m);
    
    let (k_enc, c) = encaps_internal::<800, 768>(&ML_KEM_512, &ek, &m);
    let k_dec = decaps_internal::<800, 1632, 768>(&ML_KEM_512, &dk, &c);
    
    assert_eq!(k_enc.0, k_dec.0, "Shared secrets must match");
}

#[test]
fn test_ml_kem_512_implicit_rejection() {
    let mut d = [0u8; 32];
    let mut z = [0u8; 32];
    for i in 0..32 {
        d[i] = i as u8;
        z[i] = (31 - i) as u8;
    }
    
    let (ek, dk) = keygen_internal::<800, 1632>(&ML_KEM_512, &d, &z);
    
    let mut m = [0u8; 32];
    for i in 0..32 {
        m[i] = (i * 2) as u8;
    }
    
    let (k_enc, c) = encaps_internal::<800, 768>(&ML_KEM_512, &ek, &m);
    
    // Modify ciphertext slightly to cause implicit rejection
    let mut c_modified = c.0.clone();
    c_modified[0] ^= 1;
    let c_mod_wrapped = Ciphertext(c_modified);
    
    let k_dec = decaps_internal::<800, 1632, 768>(&ML_KEM_512, &dk, &c_mod_wrapped);
    
    assert_ne!(k_enc.0, k_dec.0, "Shared secrets should not match on modified ciphertext");
}

